INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist jedes Projekt nach DIN 69901 durch bestimmte Merkmale definiert?', 2, '[{"text": "Ja", "correct": true, "because": "DIN 69901 legt Merkmale fest"}, {"text": "Nein", "correct": false, "because": "Merkmale sind nicht optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal gehört zu jedem Projekt?', 3, '[{"text": "Zeitliche Befristung", "correct": true, "because": "Projekte haben ein Ende"}, {"text": "Unendliche Dauer", "correct": false, "because": "Widerspricht der Definition"}, {"text": "Feste Teamgröße", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projekte sind einmalig. b) Projekte sind immer einfach.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einmaligkeit ist zentral, Einfachheit nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren ein Projekt nach DIN 69901?', 4, '[{"text": "Einmaligkeit", "correct": true, "because": "Kernmerkmal"}, {"text": "Risikobehaftung", "correct": true, "because": "Typisch für Projekte"}, {"text": "Routineaufgaben", "correct": false, "because": "Gegenteil von Projekten"}, {"text": "Komplexität", "correct": true, "because": "Häufig vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne klare Merkmale existieren?', 2, '[{"text": "Nein", "correct": true, "because": "Merkmale geben Struktur"}, {"text": "Ja", "correct": false, "because": "Es wäre kein Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal unterscheidet Projekte von Prozessen?', 3, '[{"text": "Einmaligkeit", "correct": true, "because": "Prozesse sind wiederholbar"}, {"text": "Teamzusammensetzung", "correct": false, "because": "Nicht entscheidend"}, {"text": "Budgetgröße", "correct": false, "because": "Kein Unterscheidungsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Komplexität ein zwingendes Merkmal eines Projekts?', 2, '[{"text": "Nein", "correct": true, "because": "Projekte können einfach sein"}, {"text": "Ja", "correct": false, "because": "Komplexität ist nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt gehört nicht zu den allgemeinen Merkmalen eines Projekts?', 3, '[{"text": "Dauerhafte Struktur", "correct": true, "because": "Projekte sind temporär"}, {"text": "Zeitliche Begrenzung", "correct": false, "because": "Ist ein Merkmal"}, {"text": "Innovative Ansätze", "correct": false, "because": "Kann zutreffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projekte sind risikobehaftet. b) Projekte haben keine Ziele.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ziele sind essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typisches Merkmal eines IT-Projekts?', 3, '[{"text": "Technische Komplexität", "correct": true, "because": "Häufig in IT-Projekten"}, {"text": "Unendliche Laufzeit", "correct": false, "because": "Projekte sind befristet"}, {"text": "Keine Planung", "correct": false, "because": "Planung ist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne zeitliche Begrenzung ein Projekt sein?', 2, '[{"text": "Nein", "correct": true, "because": "Befristung ist Kernmerkmal"}, {"text": "Ja", "correct": false, "because": "Widerspricht der Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal macht ein Projekt nach DIN 69901 einzigartig?', 3, '[{"text": "Einmaligkeit der Bedingungen", "correct": true, "because": "Definiert Projekte"}, {"text": "Wiederholbare Schritte", "correct": false, "because": "Typisch für Prozesse"}, {"text": "Feste Hierarchie", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind alle Projekte innovativ?', 2, '[{"text": "Nein", "correct": true, "because": "Innovation ist relativ"}, {"text": "Ja", "correct": false, "because": "Nicht immer erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale gehören zu einem Projekt?', 4, '[{"text": "Zeitliche Befristung", "correct": true, "because": "Kernmerkmal"}, {"text": "Risikobehaftung", "correct": true, "because": "Typisch für Projekte"}, {"text": "Permanente Organisation", "correct": false, "because": "Projekte sind temporär"}, {"text": "Einmaligkeit", "correct": true, "because": "Unterscheidet von Routine"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Teamgröße ein definierendes Merkmal eines Projekts?', 2, '[{"text": "Nein", "correct": true, "because": "Größe ist variabel"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal erhöht die Herausforderung eines Projekts?', 3, '[{"text": "Komplexität", "correct": true, "because": "Erfordert mehr Planung"}, {"text": "Kleine Dauer", "correct": false, "because": "Weniger Einfluss"}, {"text": "Einzelne Person", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Risiken ein Projekt sein?', 2, '[{"text": "Ja", "correct": true, "because": "Risiken sind nicht zwingend"}, {"text": "Nein", "correct": false, "because": "Risiken sind oft vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal grenzt Projekte von Routineaufgaben ab?', 3, '[{"text": "Einmaligkeit", "correct": true, "because": "Routine ist wiederholbar"}, {"text": "Feste Kosten", "correct": false, "because": "Nicht unterscheidend"}, {"text": "Großes Budget", "correct": false, "because": "Irrelevant für Abgrenzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projekte sind zeitlich befristet. b) Projekte sind immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten sind variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht zwingend"}, {"text": "Nur b) stimmt", "correct": "false", "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist für IT-Projekte besonders relevant?', 3, '[{"text": "Technische Innovation", "correct": true, "because": "Häufig in IT"}, {"text": "Unendliche Dauer", "correct": false, "because": "Projekte sind befristet"}, {"text": "Keine Ziele", "correct": false, "because": "Ziele sind essenziell"}]');